<?php require_once 'includes/auth.php';if(current_user()){header('Location: account.php');exit;}if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$name=trim($_POST['name']);$email=strtolower(trim($_POST['email']));$phone=trim($_POST['phone']);$pw=$_POST['password'];if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pw)<8){flash('error','Enter valid details; password must be at least 8 characters.');}else{try{$s=$pdo->prepare("INSERT INTO users(name,email,password,phone) VALUES(?,?,?,?)");$s->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT),$phone]);flash('success','Account created. Please sign in.');header('Location: login.php');exit;}catch(PDOException $e){flash('error','That email is already registered.');}}}$page_title='Sign Up';require 'includes/header.php';?>
<div class="container"><div class="form-card"><span class="eyebrow">Join ZAIN STORE</span><h1>Create account</h1><form method="post"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><div class="field"><label>Full name</label><input class="input" name="name" required></div><div class="field"><label>Email</label><input class="input" type="email" name="email" required></div><div class="field"><label>Phone</label><input class="input" name="phone"></div><div class="field"><label>Password</label><input class="input" type="password" name="password" minlength="8" required></div><button class="btn">Create account</button></form></div></div><?php require 'includes/footer.php';?>
